// The shapes of data/schematic.json (hand-written) and data/classes/*.json (generated by cmd/classgen).

export type Kind =
  | "client"
  | "service"
  | "module"
  | "core"
  | "shared"
  | "port"
  | "adapter"
  | "store"
  | "external"
  | "group";

export interface Consideration {
  ref?: string;
  title: string;
  section?: string;
  status?: "accepted" | "proposed" | "deferred";
  decision: string;
  why: string;
  tradeoff?: string;
  rejected?: string;
}

export interface SchematicNode {
  id: string;
  kind: Kind;
  name: string;
  path?: string;
  tech?: string;
  summary?: string;
  description?: string;
  // One plain sentence on why it is built this way, from the design's reasoning.
  why?: string;
  // A setting that switches it: its name, a colon, then its choices, such as "VOICE_TTS: kokoro · fake".
  setting?: string;
  considerations?: string[];
  drill?: string;
  focus?: string;
  parent?: string;
  context?: boolean;
  tag?: string;
  members?: string[];
  accent?: Kind;
  // A package of plain types every part may import, so its imports aren't drawn.
  importedFreely?: boolean;
}

export interface SchematicEdge {
  id: string;
  from: string;
  to: string;
  protocol?: string;
  send?: string;
  back?: string;
  detail?: string;
  style?: "flow" | "implements";
  considerations?: string[];
}

// A walk-through: a named story told in steps, each lighting the cards and connections it names.
export interface FlowStep {
  nodes: string[];
  edges: string[];
  caption: string;
}

export interface Flow {
  id: string;
  name: string;
  steps: FlowStep[];
}

export interface View {
  id: string;
  title: string;
  level: number;
  type?: "classes";
  lead: string;
  // Two lines on the canvas saying what the level shows and where to begin.
  start?: string;
  considerations: string[];
  flows?: Flow[];
  nodes?: SchematicNode[];
  edges?: SchematicEdge[];
  classes?: string;
  source?: string;
  root?: string;
}

export interface Schematic {
  // The design document, online; a decision's link is this with its anchor.
  design: string;
  considerations: Record<string, Consideration>;
  views: View[];
  // Go packages deliberately drawn nowhere, each with why.
  omitted?: Record<string, string>;
}

// Generated class data.
export interface ClassField {
  name: string;
  type: string;
  short: string;
  exported: boolean;
  embedded?: boolean;
  doc?: string;
}

export interface ClassMethod {
  name: string;
  signature: string;
  short: string;
  exported: boolean;
  pointer?: boolean;
  doc?: string;
  line?: number;
}

export interface ClassType {
  id: string;
  package: string;
  name: string;
  kind: "struct" | "interface" | "type";
  exported: boolean;
  doc?: string;
  file?: string;
  line?: number;
  fields: ClassField[];
  methods: ClassMethod[];
  constructors?: ClassMethod[];
  external?: boolean;
}

export interface ClassRelation {
  from: string;
  to: string;
  kind: "implements" | "holds" | "embeds";
  via?: string[];
  many?: boolean;
  pointer?: boolean;
}

export interface ClassPackage {
  path: string;
  name: string;
  doc: string;
}

export interface ClassData {
  generator: string;
  generated: string;
  module: string;
  patterns: string[];
  packages: ClassPackage[];
  types: ClassType[];
  relations: ClassRelation[];
  warnings?: string[];
}
